//! Minimal URL parser matching the observable behavior of the reference CLI.

#[derive(Debug, Clone, Default)]
pub struct URL {
    scheme: String,
    userinfo: String,
    host: String,
    port: Option<u16>,
    path: String,
    query: String,
    fragment: String,
    parsed_authority: bool,
}

impl URL {
    pub fn new(input: &str) -> Self {
        let (without_fragment, fragment) = split_once(input, '#');
        let (without_query, query) = split_once(without_fragment, '?');

        let mut url = Self {
            fragment: fragment.unwrap_or_default().to_owned(),
            query: query.unwrap_or_default().to_owned(),
            ..Self::default()
        };

        if let Some(scheme_end) = without_query.find("://") {
            url.scheme = ascii_lowercase(&without_query[..scheme_end]);
            let after_scheme = &without_query[scheme_end + 3..];
            let authority_end = after_scheme.find('/').unwrap_or(after_scheme.len());
            let authority = &after_scheme[..authority_end];
            url.path = after_scheme[authority_end..].to_owned();
            url.parsed_authority = true;
            url.parse_authority(authority);
        } else {
            url.path = without_query.to_owned();
        }

        url
    }

    fn parse_authority(&mut self, authority: &str) {
        let host_and_port = match authority.find('@') {
            Some(at) => {
                let userinfo = &authority[..at];
                if !userinfo.is_empty() {
                    self.userinfo = userinfo.to_owned();
                }
                &authority[at + 1..]
            }
            None => authority,
        };

        match host_and_port.find(':') {
            Some(colon) => {
                self.host = host_and_port[..colon].to_owned();
                self.port = parse_port(&host_and_port[colon + 1..]);
            }
            None => self.host = host_and_port.to_owned(),
        }
    }

    pub fn scheme(&self) -> &str {
        &self.scheme
    }

    pub fn authority(&self) -> String {
        if !self.parsed_authority {
            return String::new();
        }

        let mut authority = String::new();
        if !self.userinfo.is_empty() {
            authority.push_str(&self.userinfo);
            authority.push('@');
        }
        authority.push_str(&self.host);
        if let Some(port) = self.port {
            authority.push(':');
            authority.push_str(&port.to_string());
        }
        authority
    }

    pub fn userinfo(&self) -> &str {
        &self.userinfo
    }

    pub fn host(&self) -> &str {
        &self.host
    }

    pub fn port(&self) -> i32 {
        self.port.map_or(-1, i32::from)
    }

    pub fn path(&self) -> &str {
        &self.path
    }

    pub fn query(&self) -> &str {
        &self.query
    }

    pub fn fragment(&self) -> &str {
        &self.fragment
    }

    pub fn has_scheme(&self) -> bool {
        !self.scheme.is_empty()
    }

    pub fn has_authority(&self) -> bool {
        self.has_host()
    }

    pub fn has_userinfo(&self) -> bool {
        !self.userinfo.is_empty()
    }

    pub fn has_host(&self) -> bool {
        !self.host.is_empty()
    }

    pub fn has_port(&self) -> bool {
        self.port.is_some()
    }

    pub fn has_path(&self) -> bool {
        !self.path.is_empty()
    }

    pub fn has_query(&self) -> bool {
        !self.query.is_empty()
    }

    pub fn has_fragment(&self) -> bool {
        !self.fragment.is_empty()
    }

    pub fn to_string(&self) -> String {
        let mut result = String::new();
        if self.has_scheme() {
            result.push_str(&self.scheme);
            result.push_str("://");
            result.push_str(&self.authority());
        }
        result.push_str(&self.path);
        if self.has_query() {
            result.push('?');
            result.push_str(&self.query);
        }
        if self.has_fragment() {
            result.push('#');
            result.push_str(&self.fragment);
        }
        result
    }

    pub fn is_valid(&self) -> bool {
        self.has_host() || self.has_path()
    }
}

fn split_once(value: &str, delimiter: char) -> (&str, Option<&str>) {
    match value.find(delimiter) {
        Some(index) => (&value[..index], Some(&value[index + delimiter.len_utf8()..])),
        None => (value, None),
    }
}

fn ascii_lowercase(value: &str) -> String {
    value
        .bytes()
        .map(|byte| byte.to_ascii_lowercase())
        .map(char::from)
        .collect()
}

fn parse_port(text: &str) -> Option<u16> {
    let bytes = text.as_bytes();
    let mut index = 0;

    while index < bytes.len() && is_c_space(bytes[index]) {
        index += 1;
    }

    let mut negative = false;
    if index < bytes.len() && (bytes[index] == b'+' || bytes[index] == b'-') {
        negative = bytes[index] == b'-';
        index += 1;
    }

    let digits_start = index;
    let mut value: u32 = 0;
    while index < bytes.len() && bytes[index].is_ascii_digit() {
        value = value
            .saturating_mul(10)
            .saturating_add(u32::from(bytes[index] - b'0'));
        index += 1;
    }

    if index == digits_start || value > 65535 || (negative && value != 0) {
        None
    } else {
        Some(value as u16)
    }
}

fn is_c_space(byte: u8) -> bool {
    matches!(byte, b' ' | b'\t' | b'\n' | b'\r' | 0x0b | 0x0c)
}

