use url_parser::URL;

fn main() {
    let mut args = std::env::args();
    let _program = args.next();
    let Some(url) = args.next() else {
        std::process::exit(1);
    };

    let parser = URL::new(&url);

    println!("{}", parser.scheme());
    println!("{}", parser.authority());
    println!("{}", parser.userinfo());
    println!("{}", parser.host());
    println!("{}", parser.port());
    println!("{}", parser.path());
    println!("{}", parser.query());
    println!("{}", parser.fragment());

    println!("{}", as_digit(parser.has_scheme()));
    println!("{}", as_digit(parser.has_authority()));
    println!("{}", as_digit(parser.has_userinfo()));
    println!("{}", as_digit(parser.has_host()));
    println!("{}", as_digit(parser.has_port()));
    println!("{}", as_digit(parser.has_path()));
    println!("{}", as_digit(parser.has_query()));
    println!("{}", as_digit(parser.has_fragment()));

    println!("{}", parser.to_string());
    println!("{}", as_digit(parser.is_valid()));
}

fn as_digit(value: bool) -> u8 {
    u8::from(value)
}

